def bowling_score(rolls) -> int:
    try:
        rolls = list(rolls)
    except (TypeError, ValueError):
        raise ValueError("rolls must describe a complete bowling game")

    def valid_roll(value) -> bool:
        return isinstance(value, int) and not isinstance(value, bool) and 0 <= value <= 10

    def require_roll(index: int) -> int:
        if index >= len(rolls) or not valid_roll(rolls[index]):
            raise ValueError("invalid or incomplete bowling game")
        return rolls[index]

    index = 0

    # Validate and locate the first nine frames.
    for _ in range(9):
        first = require_roll(index)
        if first == 10:
            index += 1
        else:
            second = require_roll(index + 1)
            if first + second > 10:
                raise ValueError("a frame cannot score more than 10 pins")
            index += 2

    # Validate the tenth frame and its bonus rolls.
    tenth_start = index
    first = require_roll(index)
    index += 1

    if first == 10:
        second = require_roll(index)
        index += 1
        third = require_roll(index)
        index += 1

        if second != 10 and second + third > 10:
            raise ValueError("bonus rolls cannot score more than 10 pins")
    else:
        second = require_roll(index)
        index += 1

        if first + second > 10:
            raise ValueError("a frame cannot score more than 10 pins")

        if first + second == 10:
            require_roll(index)
            index += 1

    if index != len(rolls):
        raise ValueError("too many rolls")

    # Score the first nine frames.
    score = 0
    index = 0

    for _ in range(9):
        first = rolls[index]

        if first == 10:
            score += 10 + rolls[index + 1] + rolls[index + 2]
            index += 1
        else:
            second = rolls[index + 1]
            if first + second == 10:
                score += 10 + rolls[index + 2]
            else:
                score += first + second
            index += 2

    # Score the tenth frame.
    first = rolls[tenth_start]
    second = rolls[tenth_start + 1]

    if first == 10:
        score += 10 + second + rolls[tenth_start + 2]
    elif first + second == 10:
        score += 10 + rolls[tenth_start + 2]
    else:
        score += first + second

    return score
